struct Bench {
    const char* name;
    int instrs_per_iter;
    void (*fn)(long long*);
};

int main() {
    long long *d_out, h_out[2];
    cudaMalloc(&d_out, LDG_BUF_SIZE + 4096);
    cudaMemset(d_out, 0, LDG_BUF_SIZE + 4096);

    Bench benches[] = {
    {"FADD lat depth=16", 16, lat_FADD},
    {"FMUL lat depth=16", 16, lat_FMUL},
    {"FFMA lat depth=16", 16, lat_FFMA},
    {"HADD2 lat depth=16", 16, lat_HADD2},
    {"HFMA2 lat depth=16", 16, lat_HFMA2},
    {"F2FP lat depth=16", 16, lat_F2FP},
    {"LOP3 lat depth=16", 16, lat_LOP3},
    {"SHF lat depth=16", 16, lat_SHF},
    {"PRMT lat depth=16", 16, lat_PRMT},
    {"VIADD lat depth=16", 16, lat_VIADD},
    {"IADD3 lat depth=16", 16, lat_IADD3},
    {"IMAD lat depth=16", 16, lat_IMAD},
    {"SEL lat depth=16", 16, lat_SEL},
    {"REDUX lat depth=16", 16, lat_REDUX},
    {"LDS lat depth=16", 16, lat_LDS},
    {"LDG lat depth=16", 16, lat_LDG},
    };

    int n = sizeof(benches) / sizeof(benches[0]);
    printf("SASS Calibration -- SM 100a\n");
    printf("REPS=%d, 1 block, 1 warp (32 threads)\n\n", REPS);
    printf("%-55s %10s %10s %10s\n", "Kernel", "Cycles", "Cyc/instr", "Throughput");
    printf("%-55s %10s %10s %10s\n", "------", "------", "---------", "----------");

    for (int i = 0; i < n; i++) {
        cudaMemset(d_out, 0, 4096);
        benches[i].fn<<<1, 32>>>(d_out);
        cudaDeviceSynchronize();
        benches[i].fn<<<1, 32>>>(d_out);
        cudaDeviceSynchronize();
        cudaMemcpy(h_out, d_out, 2 * sizeof(long long), cudaMemcpyDeviceToHost);

        long long total = h_out[0];
        double per_instr = (double)total / (REPS * benches[i].instrs_per_iter);
        double throughput = 1.0 / per_instr;

        printf("%-55s %10lld %10.2f %10.4f\n",
               benches[i].name, total, per_instr, throughput);
    }

    printf("\n@@CALIBRATION\n");
    cudaFree(d_out);
    return 0;
}
